functional-example.query:
let $books := //book
let $years := for $b in $books return number($b/year)
let $count := count($years)
let $sum := sum($years)
return <average-year>{$sum div $count}</average-year>

module-example.query:
import module namespace math = "http://www.w3.org/2005/xpath-functions/math";

for $b in //book
let $year := number($b/year)
where math:sin($year) > 0
return $b/title
